# Free shipping

Implement `qualifiesForFreeShipping(subtotalCents)` in `src/shipping.js`.

- Accept non-negative integer cents.
- Return `true` for subtotals of 5,000 cents or more.
- Return `false` below 5,000 cents.
- Reject negative or non-integer input with `TypeError`.
{
  "name": "tdd-free-shipping-fixture",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test"
  }
}
export function qualifiesForFreeShipping() {
  return false;
}

export function qualifiesForFreeShipping(subtotalCents) {
  if (!Number.isInteger(subtotalCents) || subtotalCents < 0) {
    throw new TypeError('Subtotal must be non-negative integer cents');
  }
  return subtotalCents >= 5_000;
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { qualifiesForFreeShipping } from '../src/shipping.js';

test('free shipping begins at 5,000 cents', () => {
  assert.equal(qualifiesForFreeShipping(0), false);
  assert.equal(qualifiesForFreeShipping(4_999), false);
  assert.equal(qualifiesForFreeShipping(5_000), true);
  assert.equal(qualifiesForFreeShipping(5_001), true);
});

test('rejects negative and non-integer cents with TypeError', () => {
  for (const subtotal of [-1, 4_999.5, 5_000.5, NaN, Infinity, '5000', null, undefined]) {
    assert.throws(() => qualifiesForFreeShipping(subtotal), TypeError);
  }
});
